package sinchonthon.demo.domain.discovery.service;
import java.util.*; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import sinchonthon.demo.domain.discovery.dto.*; import sinchonthon.demo.domain.discovery.entity.*; import sinchonthon.demo.domain.discovery.repository.DraftOrderRepository; import sinchonthon.demo.domain.member.entity.*; import sinchonthon.demo.domain.member.repository.MemberRepository; import sinchonthon.demo.domain.store.*; import sinchonthon.demo.global.exception.*; import sinchonthon.demo.global.response.GeneralErrorCode;
@Service @RequiredArgsConstructor public class DiscoveryService {private final RecruitmentSlotRepository slots;private final DraftOrderRepository drafts;private final MemberRepository members;@Transactional(readOnly=true) public List<RecruitmentSlot> list(){return slots.findAllByStatusOrderByPickupAtAsc(RecruitmentSlotStatus.RECRUITING);}@Transactional(readOnly=true) public RecruitmentSlot get(Long id){return slots.findById(id).filter(x->x.getStatus()==RecruitmentSlotStatus.RECRUITING).orElseThrow(()->new BusinessException(GeneralErrorCode.SLOT_NOT_FOUND));}@Transactional public DraftOrder create(Long memberId,Long slotId,CreateDraftOrderRequest r){Member student=student(memberId);RecruitmentSlot slot=get(slotId);Map<Long,Integer> q=quantities(r.items());List<Menu> ms=slot.getStore().getMenus().stream().filter(x->q.containsKey(x.getId())).toList();if(ms.size()!=q.size())throw new BusinessException(GeneralErrorCode.INVALID_REQUEST);int total=ms.stream().mapToInt(x->Math.toIntExact(x.getPrice())*q.get(x.getId())).sum();DraftOrder d=drafts.save(new DraftOrder(student,slot,total));ms.forEach(x->d.addItem(x,q.get(x.getId())));d.setDraftOrderNumber("DRAFT-"+d.getId());return d;}@Transactional public DraftOrder pay(Long memberId,Long slotId,Long draftId){Member student=student(memberId);DraftOrder d=drafts.findByIdAndStudentId(draftId,student.getId()).orElseThrow(()->new BusinessException(GeneralErrorCode.NOT_FOUND));if(!d.getRecruitmentSlot().getId().equals(slotId)||d.getStatus()!=DraftOrderStatus.DRAFT)throw new BusinessException(GeneralErrorCode.INVALID_REQUEST);RecruitmentSlot slot=get(slotId);slot.participate();d.pay();return d;}private Member student(Long id){Member m=members.findById(id).orElseThrow(()->new BusinessException(GeneralErrorCode.UNAUTHORIZED));if(m.getRole()!=MemberRole.STUDENT)throw new BusinessException(GeneralErrorCode.FORBIDDEN);return m;}private Map<Long,Integer> quantities(List<MenuItemRequest> items){Map<Long,Integer> r=new HashMap<>();for(MenuItemRequest i:items)if(r.putIfAbsent(i.menuId(),i.quantity())!=null)throw new BusinessException(GeneralErrorCode.INVALID_REQUEST);return r;}}
